export class CustomerDashboard implements OnInit {
  readonly token = signal<QueueToken|null>(null); readonly history = signal<QueueToken[]>([]); readonly appointments = signal<Appointment[]>([]); readonly error = signal(''); readonly busy = signal(false);
  constructor(private readonly queues: QueueService, private readonly appointmentsApi: AppointmentService, private readonly auth: AuthService) {}
  get name(): string { return this.auth.user()?.fullName.split(' ')[0] ?? 'there'; }
  get greeting(): string { const hour = new Date().getHours(); return hour < 12 ? 'morning' : hour < 17 ? 'afternoon' : 'evening'; }
  ngOnInit(): void {
    this.queues.current().subscribe({next:value=>this.token.set(value),error:e=>{if(e.status!==404)this.error.set('Your active queue is temporarily unavailable. Please refresh to try again.');}});
    this.queues.history(0,4).subscribe({next:value=>this.history.set(value.content),error:()=>this.error.set('Recent queue history is unavailable.')});
    this.appointmentsApi.list().subscribe({next:value=>this.appointments.set(value),error:()=>undefined});
  }
  cancel(): void { const current=this.token(); if(!current)return; this.busy.set(true); this.queues.cancel(current.id).subscribe({next:()=>this.token.set(null),error:()=>this.error.set('We couldn’t cancel your token. Please try again.'),complete:()=>this.busy.set(false)}); }
}

@Component({ standalone: true, imports: [CommonModule, ReactiveFormsModule, LucideSearch], template: `
<div class="page-heading"><div><span class="eyebrow">YOUR NEXT VISIT STARTS HERE</span><h1>Find a service.</h1><p>Explore branches and see what the wait looks like before you go.</p></div></div><form class="discovery-search" [formGroup]="form" (ngSubmit)="search()"><span><svg lucideSearch size="19"></svg></span><input formControlName="query" placeholder="Search services, branches, organizations…"><button class="button button-primary">Search</button></form><div class="filter-row"><span>Browse nearby</span><button class="filter-chip" [class.active]="selectedType()==='ALL'" (click)="selectedType.set('ALL')">All types</button><button class="filter-chip" [class.active]="selectedType()==='HEALTHCARE'" (click)="selectedType.set('HEALTHCARE')">Healthcare</button><button class="filter-chip" [class.active]="selectedType()==='GOVERNMENT'" (click)="selectedType.set('GOVERNMENT')">Public services</button><button class="filter-chip" [class.active]="selectedType()==='FINANCIAL'" (click)="selectedType.set('FINANCIAL')">Financial</button><button class="filter-chip" [class.active]="selectedType()==='PERSONAL_CARE'" (click)="selectedType.set('PERSONAL_CARE')">Personal care</button><button class="filter-chip" [class.active]="availableOnly()" (click)="availableOnly.update(x=>!x)">Open now</button><button class="filter-chip" (click)="sortByWait.update(x=>!x)">Sort by wait ↕</button></div>@if(loading()){<div class="loading-state">Finding available branches…</div>}@else if(error()){<div class="empty-panel"><span>⌑</span><h2>Branches aren’t available yet.</h2><p>{{error()}} Check that the QueueLess API is running, then try again.</p><button class="button button-secondary" (click)="load()">Try again</button><small>Branch discovery needs the Spring Boot <code>GET /branches</code> endpoint.</small></div>}@else if(branches().length){<div class="branch-grid">@if(filteredBranches().length){@for(branch of filteredBranches();track branch.id){<article class="branch-card"><div class="branch-art"><span class="branch-art-symbol">{{symbol(branch.name)}}</span><span class="branch-open" [class.closed]="!branch.active"><i></i>{{branch.active?'Open now':'Closed'}}</span><span class="branch-art-label">{{branch.organizationName}}</span></div><div class="branch-card-body"><h2>{{branch.name}}</h2><p>⌖ {{branch.address}}</p><div class="branch-services">@for(s of (branch.services ?? []).slice(0,2);track s.id){<span>{{s.name}}</span>}</div><div class="branch-wait"><span>◷ {{branch.estimatedWaitMinutes == null ? 'Wait time unavailable' : '~'+branch.estimatedWaitMinutes+' min wait'}}</span><span>{{branch.activeQueueLength == null ? 'Queue info unavailable' : branch.activeQueueLength+' waiting'}}</span></div><button class="button button-primary button-small" [disabled]="!branch.active" (click)="select(branch)">View services <span>↗</span></button></div></article>}}@else{<p class="compact-empty">No branches match these filters. Clear a filter to see more results.</p>}</div>}@else{<div class="empty-panel"><span>⌕</span><h2>Let’s find your next stop.</h2><p>Search for an organization, branch or service to see what’s nearby.</p><small>Branch discovery connects to your QueueLess organization directory.</small></div>}
` })
export class DiscoveryPage implements OnInit {
  readonly selectedType=signal('ALL');readonly availableOnly=signal(false);readonly sortByWait=signal(false);readonly branches = signal<Branch[]>([]); readonly loading = signal(false); readonly error = signal(''); readonly form;
  constructor(private readonly fb:FormBuilder,private readonly api:BranchService,private readonly router:Router){this.form=this.fb.group({query:['']});}
  ngOnInit():void{this.load();}
  load():void{this.loading.set(true);this.error.set('');this.api.search(this.form.controls.query.value??'').pipe(finalize(()=>this.loading.set(false))).subscribe({next:v=>this.branches.set(v),error:()=>this.error.set('The service directory could not be reached.')});}
  search():void{this.load();}
  select(branch:Branch):void{void this.router.navigate(['/branches',branch.id]);}
  filteredBranches():Branch[]{let values=this.branches().filter(branch=>{const category=(branch.organizationType??'').toUpperCase();const type=this.selectedType();const matchesType=type==='ALL'||category.includes(type)||(type==='HEALTHCARE'&&/(HOSPITAL|CLINIC|HEALTH)/.test(category))||(type==='GOVERNMENT'&&/(PUBLIC|GOVERNMENT|CIVIC)/.test(category))||(type==='FINANCIAL'&&/(BANK|FINANCE)/.test(category))||(type==='PERSONAL_CARE'&&/(SALON|WELLNESS|PERSONAL)/.test(category));return matchesType&&(!this.availableOnly()||this.isOpen(branch));});if(this.sortByWait())values=values.slice().sort((a,b)=>(a.estimatedWaitMinutes??Number.MAX_SAFE_INTEGER)-(b.estimatedWaitMinutes??Number.MAX_SAFE_INTEGER));return values;}
  isOpen(branch:Branch):boolean{if(!branch.active)return false;if(!branch.openingTime||!branch.closingTime)return branch.active;const now=new Date().toTimeString().slice(0,5);return now>=branch.openingTime&&now<=branch.closingTime;}
  symbol(name:string):string{return name.slice(0,1).toUpperCase();}
}

@Component({ standalone: true, imports: [CommonModule, ReactiveFormsModule], template: `
<div class="page-heading"><div><span class="eyebrow">TAKE YOUR PLACE IN LINE</span><h1>Join a queue.</h1><p>Choose a service and we'll save your place.</p></div></div><section class="panel join-panel"><div class="join-steps"><span class="step-active"><i>1</i> Organization & branch</span><span><i>2</i> Service</span><span><i>3</i> Confirm</span></div><form [formGroup]="form"><label>Choose an organization<select formControlName="organizationId" (change)="selectOrganization()"><option value="">Select an organization</option>@for(org of organizations;track org.id){<option [value]="org.id">{{org.name}}</option>}</select></label><label>Choose a branch<select formControlName="branchId" (change)="loadServices()"><option value="">Select a branch</option>@for(b of filteredBranches();track b.id){<option [value]="b.id">{{b.name}} — {{b.address}}</option>}</select></label><label>Choose a service<select formControlName="serviceId"><option value="">Select a service</option>@for(s of services();track s.id){<option [value]="s.id">{{s.name}}</option>}</select></label></form>@if(selectedBranch()){<div class="branch-wait"><span>{{selectedBranch()?.activeQueueLength??'—'}} customers waiting</span><span>{{selectedBranch()?.estimatedWaitMinutes==null?'Wait estimate unavailable':'~'+selectedBranch()?.estimatedWaitMinutes+' min'}}</span></div>}@if(error()){<p class="form-error">{{error()}}</p>}<button class="button button-primary" [disabled]="busy() || !form.controls.serviceId.value" (click)="join()">{{busy()?'Joining…':'Confirm and join queue'}} <span>↗</span></button><p class="api-note">Availability values are shown only when returned by the backend.</p></section>
` })
export class JoinQueuePage implements OnInit {
  readonly branches=signal<Branch[]>([]);readonly services=signal<{id:string;name:string}[]>([]);readonly error=signal('');readonly busy=signal(false);readonly form;
  constructor(private readonly fb:FormBuilder,private readonly branchApi:BranchService,private readonly serviceApi:ServiceManagementService,private readonly queue:QueueService,private readonly router:Router,private readonly route:ActivatedRoute){this.form=this.fb.group({organizationId:['',Validators.required],branchId:['',Validators.required],serviceId:['',Validators.required]});}
  get organizations():{id:string;name:string}[]{return [...new Map(this.branches().map(branch=>[branch.organizationId??branch.organizationName,{id:branch.organizationId??branch.organizationName,name:branch.organizationName}])).values()];}
  filteredBranches():Branch[]{const org=this.form.controls.organizationId.value;return this.branches().filter(branch=>(branch.organizationId??branch.organizationName)===org);}
  selectedBranch():Branch|undefined{return this.branches().find(branch=>branch.id===this.form.controls.branchId.value);}
  ngOnInit():void{this.branchApi.search().subscribe({next:v=>{this.branches.set(v);const branchId=this.route.snapshot.queryParamMap.get('branchId');const orgId=this.route.snapshot.queryParamMap.get('organizationId');if(orgId)this.form.controls.organizationId.setValue(orgId);if(branchId){this.form.controls.branchId.setValue(branchId);this.loadServices();}},error:()=>this.error.set('Branches could not be loaded. Check the API connection.')});}
  selectOrganization():void{this.form.controls.branchId.setValue('');this.form.controls.serviceId.setValue('');this.services.set([]);}
  loadServices():void{const id=this.form.controls.branchId.value;if(!id)return;this.form.controls.serviceId.setValue('');this.form.controls.organizationId.setValue(this.selectedBranch()?.organizationId??this.selectedBranch()?.organizationName??'');this.serviceApi.byBranch(id).subscribe({next:v=>{this.services.set(v.filter(s=>s.active));const requested=this.route.snapshot.queryParamMap.get('serviceId');if(requested&&v.some(service=>service.id===requested&&service.active))this.form.controls.serviceId.setValue(requested);},error:()=>this.error.set('Services could not be loaded for this branch.')});}
  join():void{const id=this.form.controls.serviceId.value;if(!id)return;this.busy.set(true);this.queue.join(id).subscribe({next:v=>void this.router.navigate(['/track',v.id]),error:e=>{this.error.set(e?.error?.message??'We couldn’t join the queue. Please try again.');this.busy.set(false);}});}
}

@Component({standalone:true,imports:[CommonModule,RouterLink],template:`<section class="panel track-panel"><a routerLink="/customer" class="back-link">← Back to overview</a>@if(token()){<div class="track-hero"><span class="eyebrow">YOUR QUEUE TOKEN</span><div class="token-number-large">{{token()?.tokenNumber}}</div><span class="status-label"><i></i>{{token()?.status}}</span><p class="connection-state" [class.offline]="connection()==='offline'">{{connection()==='live'?'Live updates via polling':connection()==='offline'?'Reconnecting automatically':'Connecting…'}}</p></div><div class="track-progress"><div class="track-step done"><i>✓</i><span>Joined queue</span><small>{{token()?.joinedAt | date:'h:mm a'}}</small></div><div class="track-step current"><i>{{token()?.position}}</i><span>Waiting your turn</span><small>{{token()?.peopleAhead}} people ahead</small></div><div class="track-step"><i>3</i><span>Service begins</span></div></div><div class="wait-stats"><div><small>ESTIMATED WAIT</small><b>~{{token()?.estimatedWaitMinutes}} <span>min</span></b></div><div><small>CURRENTLY SERVING</small><b>{{token()?.currentServingToken??'—'}}</b></div></div><div class="panel-foot"><span>{{token()?.serviceName}} · {{token()?.branchName}}</span><small>Last updated {{updated()|date:'h:mm:ss a'}}</small></div><div class="token-actions"><button class="subtle-link" (click)="cancel()" [disabled]="cancelBusy()||token()?.status==='CALLED'||token()?.status==='IN_SERVICE'||token()?.status==='COMPLETED'||token()?.status==='CANCELLED'||token()?.status==='NO_SHOW'">Cancel token</button><small>{{error()}}</small></div>}@else if(error()){<div class="empty-state"><span class="empty-icon">⌑</span><h3>Queue tracking is unavailable</h3><p>{{error()}}</p><button class="button button-secondary" (click)="load()">Retry on next check</button></div>}@else{<div class="loading-state">Loading your queue…</div>}</section>`})
export class TrackingPage implements OnInit {
  readonly token=signal<QueueToken|null>(null);readonly error=signal('');readonly updated=signal(new Date());readonly connection=signal<'connecting'|'live'|'offline'>('connecting');readonly cancelBusy=signal(false);
  constructor(private readonly route:ActivatedRoute,private readonly queues:QueueService,private readonly destroyRef:DestroyRef){}
  ngOnInit():void{const id=this.route.snapshot.paramMap.get('id');if(!id){this.error.set('A queue token was not provided.');return;}timer(0,15000).pipe(exhaustMap(()=>{this.connection.set('connecting');return this.queues.track(id).pipe(tap(value=>{this.token.set(value);this.updated.set(new Date());this.error.set('');this.connection.set('live');}),catchError(()=>{this.connection.set('offline');this.error.set('We can’t reach the queue service. Automatic polling will retry.');return EMPTY;}));}),takeUntilDestroyed(this.destroyRef)).subscribe();}
  load():void{this.error.set('');this.connection.set('connecting');}
  cancel():void{const token=this.token();if(!token)return;this.cancelBusy.set(true);this.queues.cancel(token.id).pipe(finalize(()=>this.cancelBusy.set(false))).subscribe({next:()=>{this.token.set(null);this.error.set('Queue token cancelled.');},error:()=>this.error.set('The token could not be cancelled. Please try again.')});}
}

@Component({standalone:true,imports:[CommonModule],template:`<div class="page-heading"><div><span class="eyebrow">BRANCH OPERATIONS</span><h1>Today at your counter.</h1><p>Keep the line moving with clear, simple queue controls.</p></div><div class="assignment-strip"><span>Branch <b>{{assignment()?.branch??'Loading…'}}</b></span><span>Counter <b>{{assignment()?.counter??'—'}}</b></span><span>Service <b>{{assignment()?.service??'—'}}</b></span></div></div>@if(notice()){<p class="success-message">{{notice()}}</p>}<div class="kpi-grid"><div class="kpi-card"><small>WAITING</small><b>{{queue().length}}</b><span>Customers in line</span></div><div class="kpi-card"><small>COMPLETED TODAY</small><b>{{completed()}}</b><span>Services completed</span></div><div class="kpi-card"><small>NO-SHOWS TODAY</small><b>{{noShows()}}</b><span>Queue no-shows</span></div></div><section class="panel queue-list"><div class="panel-head"><div><span class="eyebrow">LIVE QUEUE</span><h2>Waiting customers</h2></div><button class="button button-primary button-small" (click)="action('call-next')" [disabled]="busy()">Call next <span>↗</span></button></div>@if(error()){<div class="empty-state"><span class="empty-icon">⌑</span><h3>Queue controls need a backend connection</h3><p>{{error()}}</p><small>Requires queue management APIs and an assigned staff account.</small></div>}@else if(queue().length){@for(item of queue();track item.id){<div class="activity-row"><span class="queue-token">{{item.tokenNumber}}</span><span><b>{{item.customerName??'Customer'}}</b><small>{{item.serviceName}} · {{item.peopleAhead}} people ahead · ~{{item.estimatedWaitMinutes}} min</small></span><div class="row-actions"><button [disabled]="busy()||item.status!=='CALLED'" (click)="action('recall',item.id)">Recall</button><button [disabled]="busy()||item.status!=='CALLED'" (click)="action('start',item.id)">Start service</button><button [disabled]="busy()||(item.status!=='WAITING'&&item.status!=='CALLED')" (click)="action('no-show',item.id)">No-show</button></div></div>}}@else{<div class="compact-empty">No waiting customers are available from the service API.</div>}</section><div class="action-dock"><button [disabled]="!current()||current()?.status!=='CALLED'||busy()" (click)="action('recall',current()?.id)">Recall</button><button [disabled]="!current()||current()?.status!=='CALLED'||busy()" (click)="action('start',current()?.id)">Start service</button><button class="button button-primary" [disabled]="!current()||current()?.status!=='IN_SERVICE'||busy()" (click)="action('complete',current()?.id)">Complete service</button></div>`})
export class StaffDashboard implements OnInit {
 readonly queue=signal<QueueToken[]>([]);readonly current=signal<QueueToken|null>(null);readonly assignment=signal<{branch:string;counter:string;service:string}|null>(null);readonly error=signal('');readonly notice=signal('');readonly busy=signal(false);readonly completed=signal(0);readonly noShows=signal(0);
 constructor(private readonly queues:QueueService,private readonly dialog:MatDialog,private readonly users:UserService){}
 ngOnInit():void{this.refresh();this.refreshStats();this.users.profile().subscribe({next:user=>this.assignment.set({branch:user.assignedBranch??'Not assigned',counter:user.assignedCounter??'Not assigned',service:user.assignedService??'Not assigned'}),error:()=>undefined});}
 refreshStats():void{const today=new Date().toISOString().slice(0,10);this.queues.history(0,100,{date:today}).subscribe({next:page=>{this.completed.set(page.content.filter(item=>item.status==='COMPLETED').length);this.noShows.set(page.content.filter(item=>item.status==='NO_SHOW').length);},error:()=>undefined});}
 refresh():void{this.queues.active().subscribe({next:v=>{this.queue.set(v);this.current.set(v.find(x=>x.status==='CALLED'||x.status==='IN_SERVICE')??null);},error:()=>this.error.set('The active queue endpoint is not available. Connect the backend and refresh to load customers.')});}
 action(action:'call-next'|'recall'|'start'|'complete'|'no-show',id?:string):void{if(action==='no-show'){this.dialog.open(ConfirmDialogComponent,{data:{title:'Mark customer as no-show?',message:'This removes the customer from the active queue. You can’t undo this action.',confirmLabel:'Mark no-show'}}).afterClosed().subscribe(confirmed=>{if(confirmed)this.performAction(action,id);});return;}this.performAction(action,id);}
 private performAction(action:'call-next'|'recall'|'start'|'complete'|'no-show',id?:string):void{this.busy.set(true);const request=id?this.queues.action(id,action):this.queues.callNext();request.subscribe({next:()=>{this.refreshStats();this.notice.set(action==='complete'?'Service completed.':action==='call-next'?'Next customer called.':action==='start'?'Service started.':action==='recall'?'Customer recalled.':'Customer marked no-show.');this.busy.set(false);this.refresh();},error:()=>{this.error.set('That queue action could not be completed. Please try again.');this.busy.set(false);}});}
}

@Component({standalone:true,imports:[CommonModule,BaseChartDirective],template:`<div class="page-heading"><div><span class="eyebrow">OPERATIONS OVERVIEW</span><h1>Good day. Here's your branch at a glance.</h1><p>Operational performance and customer flow for today.</p></div><span class="date-select">Today⌄</span></div><div class="kpi-grid"><div class="kpi-card"><small>CUSTOMERS TODAY</small><b>{{metric('customersToday')}}</b><span>Live from operations</span></div><div class="kpi-card"><small>WAITING NOW</small><b>{{metric('customersWaiting')}}</b><span>Across active queues</span></div><div class="kpi-card"><small>SERVED TODAY</small><b>{{metric('customersServed')}}</b><span>Completed services</span></div><div class="kpi-card"><small>AVG. WAIT TIME</small><b>{{metric('averageWaitingMinutes')}}<small> min</small></b><span>Across services</span></div></div><div class="dashboard-grid manager-grid"><section class="panel chart-panel"><div class="panel-head"><div><span class="eyebrow">CUSTOMER FLOW</span><h2>Customers served per hour</h2></div><span class="api-tag">LIVE DATA</span></div>@if(hasSeries(charts()?.servedPerHour)){<div class="chart-canvas"><canvas baseChart [data]="barData(charts()?.servedPerHour)" [options]="chartOptions" type="bar"></canvas></div>}@else{<div class="empty-chart">No hourly analytics returned by the backend.</div>}</section><section class="panel chart-panel"><span class="eyebrow">SERVICE PERFORMANCE</span><h2>Average wait by service</h2>@if(hasSeries(charts()?.averageWaitByService)){<div class="chart-canvas"><canvas baseChart [data]="barData(charts()?.averageWaitByService)" [options]="chartOptions" type="bar"></canvas></div>}@else{<div class="empty-chart">No service wait data is available.</div>}</section><section class="panel chart-panel"><span class="eyebrow">QUEUE VOLUME</span><h2>Daily volume</h2>@if(hasSeries(charts()?.dailyVolume)){<div class="chart-canvas"><canvas baseChart [data]="barData(charts()?.dailyVolume)" [options]="chartOptions" type="bar"></canvas></div>}@else{<div class="empty-chart">No daily queue volume is available.</div>}</section><section class="panel chart-panel"><span class="eyebrow">COUNTER UTILIZATION</span><h2>Utilization by counter</h2>@if(hasSeries(charts()?.counterUtilization)){<div class="chart-canvas"><canvas baseChart [data]="barData(charts()?.counterUtilization)" [options]="chartOptions" type="bar"></canvas></div>}@else{<div class="empty-chart">No counter utilization data is available.</div>}</section><section class="panel chart-panel"><span class="eyebrow">QUEUE STATUS</span><h2>Status distribution</h2>@if(hasSeries(charts()?.queueStatuses)){<div class="chart-canvas"><canvas baseChart [data]="doughnutData(charts()?.queueStatuses)" [options]="doughnutOptions" type="doughnut"></canvas></div>}@else{<div class="empty-chart">No queue status distribution is available.</div>}</section><section class="panel metric-panel"><span class="eyebrow">SERVICE PERFORMANCE</span><h2>Branch health</h2><div class="metric-line"><span>Average service duration</span><b>{{metric('averageServiceMinutes')}}{{summary()?' min':'—'}}</b></div><div class="metric-line"><span>Active counters</span><b>{{metric('activeCounters')}}</b></div><div class="metric-line"><span>No-show rate</span><b>{{metric('noShowPercentage')}}{{summary()?'%':'—'}}</b></div><div class="metric-line"><span>Counter utilization</span><b>{{metric('counterUtilization')}}{{summary()?'%':'—'}}</b></div></section></div><p class="inline-error" *ngIf="error()">{{error()}} Analytics are shown only when provided by the backend.</p>`})
export class ManagerDashboard implements OnInit {
 readonly summary=signal<Record<string,number>|null>(null);readonly charts=signal<AnalyticsCharts|null>(null);readonly error=signal('');readonly chartOptions:ChartOptions<'bar'>={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true}}};readonly doughnutOptions:ChartOptions<'doughnut'>={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}};
 constructor(private readonly analytics:AnalyticsService){}
 ngOnInit():void{this.analytics.summary().subscribe({next:v=>this.summary.set(v),error:()=>this.error.set('Analytics data is not available yet.')});this.analytics.charts().subscribe({next:v=>this.charts.set(v),error:()=>this.error.set('Chart data is not available yet.')});}
 metric(key:string):string|number{return this.summary()?.[key]??(this.summary()?'—':'—');}
 hasSeries(series?:ChartSeries):boolean{return !!series&&series.labels.length>0&&series.values.length>0;}
 barData(series?:ChartSeries):ChartData<'bar'>{return {labels:series?.labels??[],datasets:[{label:'Backend data',data:series?.values??[],backgroundColor:'#5d88c4',borderRadius:5}]};}
 doughnutData(series?:ChartSeries):ChartData<'doughnut'>{return {labels:series?.labels??[],datasets:[{data:series?.values??[],backgroundColor:['#5d88c4','#7db395','#f0bc77','#b3a1df','#d58e84']}]};}
}

@Component({standalone:true,imports:[CommonModule,ReactiveFormsModule],template:`<div class="page-heading"><div><span class="eyebrow">WORKSPACE MANAGEMENT</span><h1>{{title}}.</h1><p>Manage your organization's day-to-day setup.</p></div><button class="button button-primary" (click)="create()">{{addLabel}} <span>↗</span></button></div><form class="discovery-search management-search" [formGroup]="searchForm" (ngSubmit)="load()"><span>⌕</span><input formControlName="query" placeholder="Search {{title.toLowerCase()}}…"><button class="button button-secondary">Search</button></form>@if(message()){<p class="management-message" [class.inline-error]="failed()">{{message()}}</p>}@if(editing()){<section class="panel editor-panel"><div class="panel-head"><div><span class="eyebrow">{{editingId()?'EDIT':'NEW'}} {{title.toUpperCase()}}</span><h2>{{editingId()?'Update':'Create'}} {{title.toLowerCase().replace(/s$/,'')}}</h2></div><button class="subtle-button" type="button" (click)="editing.set(false)">Close</button></div><form [formGroup]="editForm" (ngSubmit)="save()" class="resource-form">@for(field of fields;track field.name){<label [class.checkbox-label]="field.type==='checkbox'">{{field.label}}@if(field.type==='checkbox'){<input type="checkbox" [formControlName]="field.name"> <span>Active</span>}@else{<input [type]="field.type" [formControlName]="field.name" [placeholder]="field.placeholder??''" [min]="field.type==='number'?1:null">}</label>}<div class="editor-actions"><button class="button button-secondary" type="button" (click)="editing.set(false)">Cancel</button><button class="button button-primary" [disabled]="saving()">{{saving()?'Saving…':'Save changes'}}</button></div></form></section>}<section class="panel management-panel"><div class="panel-head"><div><span class="eyebrow">YOUR ORGANIZATION</span><h2>{{title}} directory</h2></div><button class="subtle-link" (click)="load()">Refresh ↻</button></div>@if(loading()){<p class="loading-state">Loading {{title.toLowerCase()}}…</p>}@else if(items().length){@for(item of items();track item['id']){<div class="activity-row"><span class="activity-icon">◈</span><span><b>{{item['name']??item['fullName']??item['tokenNumber']}}</b><small>{{item['address']??item['email']??item['status']}}</small></span><span class="activity-status">{{item['active']===false?'Inactive':'Active'}}</span><button class="subtle-link" (click)="edit(item)">Edit</button><button class="subtle-button" (click)="toggle(item)">{{item['active']===false?'Activate':'Deactivate'}}</button></div>}}@else{<div class="empty-state"><span class="empty-icon">⌕</span><h3>No {{title.toLowerCase()}} to show</h3><p>Create the first entry or check the backend connection.</p><small>Integration endpoint: {{endpoint}}</small></div>}</section>`})
export class ManagementPage {
 readonly items=signal<Record<string,unknown>[]>([]);readonly message=signal('');readonly failed=signal(false);readonly loading=signal(false);readonly saving=signal(false);readonly editing=signal(false);readonly editingId=signal<string|null>(null);readonly searchForm;readonly editForm=new FormRecord<FormControl<string|boolean>>({});readonly fields: {name:string;label:string;type:'text'|'time'|'number'|'tel'|'email'|'checkbox';placeholder?:string;required?:boolean;min?:number}[];
 constructor(private readonly route:ActivatedRoute,private readonly fb:FormBuilder,private readonly api:ManagementApiService){this.searchForm=this.fb.group({query:['']});this.fields=this.fieldsFor(this.route.snapshot.data['endpoint'] as ManagementResource);this.load();}
 get title():string{return this.route.snapshot.data['title'] as string??'Management';}
 get endpoint():string{return `${environment.apiBaseUrl}/${this.route.snapshot.data['endpoint'] as string??'management'}`;}
 get addLabel():string{return `Add ${this.title.toLowerCase().replace(/s$/,'')}`;}
 private resource():ManagementResource{return this.route.snapshot.data['endpoint'] as ManagementResource;}
 load():void{this.loading.set(true);this.api.list(this.resource(),this.searchForm.controls.query.value??'').pipe(finalize(()=>this.loading.set(false))).subscribe({next:v=>{this.items.set(v);this.failed.set(false);this.message.set('');},error:()=>{this.failed.set(true);this.message.set(`The ${this.title.toLowerCase()} endpoint is unavailable. Configure the matching backend contract.`);}});}
 create():void{this.editingId.set(null);this.buildForm();this.editing.set(true);this.message.set('');}
 edit(item:Record<string,unknown>):void{this.editingId.set(String(item['id']??''));this.buildForm(item);this.editing.set(true);this.message.set('');}
 save():void{if(this.editForm.invalid){this.editForm.markAllAsTouched();return;}this.saving.set(true);const values=this.editForm.getRawValue();const payload:Record<string,unknown>={};for(const field of this.fields){const value=values[field.name];if(field.type==='number')payload[field.name]=value===''?null:Number(value);else if((field.name==='serviceIds'||field.name==='holidayDates')&&typeof value==='string')payload[field.name]=value.split(',').map(part=>part.trim()).filter(Boolean);else payload[field.name]=value;}this.api.save(this.resource(),payload,this.editingId()||undefined).pipe(finalize(()=>this.saving.set(false))).subscribe({next:()=>{this.failed.set(false);this.message.set(`${this.title.slice(0,-1)} saved.`);this.editing.set(false);this.load();},error:()=>{this.failed.set(true);this.message.set(`Could not save ${this.title.toLowerCase().replace(/s$/,'')}. Check required backend fields and try again.`);}});}
 toggle(item:Record<string,unknown>):void{const id=String(item['id']??'');if(!id)return;this.api.setActive(this.resource(),id,item['active']===false).subscribe({next:()=>this.load(),error:()=>{this.failed.set(true);this.message.set('Could not update active status.');}});}
 private buildForm(item?:Record<string,unknown>):void{for(const key of Object.keys(this.editForm.controls))this.editForm.removeControl(key);for(const field of this.fields){const value=item?.[field.name];const initial=field.type==='checkbox'?(typeof value==='boolean'?value:true):(Array.isArray(value)?value.join(', '):value==null?'':String(value));const validators=field.required?[Validators.required]:[];if(field.type==='number')validators.push(Validators.min(field.min??0));this.editForm.addControl(field.name,new FormControl<string|boolean>(initial,{nonNullable:true,validators}));}}
 private fieldsFor(resource:ManagementResource):typeof this.fields{const byResource:Record<string,typeof this.fields>={branches:[{name:'name',label:'Branch name',type:'text',required:true},{name:'address',label:'Address',type:'text',required:true},{name:'phone',label:'Phone number',type:'tel'},{name:'openingTime',label:'Opening time',type:'time'},{name:'closingTime',label:'Closing time',type:'time'},{name:'organizationId',label:'Organization ID',type:'text',required:true},{name:'active',label:'Status',type:'checkbox'}],services:[{name:'name',label:'Service name',type:'text',required:true},{name:'description',label:'Description',type:'text'},{name:'branchId',label:'Branch ID',type:'text',required:true},{name:'averageDurationMinutes',label:'Average service duration (minutes)',type:'number',required:true},{name:'maxQueueCapacity',label:'Maximum queue capacity',type:'number',required:true},{name:'active',label:'Status',type:'checkbox'}],counters:[{name:'name',label:'Counter name',type:'text',required:true},{name:'serviceId',label:'Service ID',type:'text',required:true},{name:'staffId',label:'Assigned staff ID',type:'text'},{name:'active',label:'Status',type:'checkbox'}],staff:[{name:'fullName',label:'Full name',type:'text',required:true},{name:'email',label:'Email',type:'email',required:true},{name:'phone',label:'Phone number',type:'tel'},{name:'branchId',label:'Branch ID',type:'text',required:true},{name:'serviceIds',label:'Service IDs (comma separated)',type:'text'},{name:'active',label:'Status',type:'checkbox'}],users:[{name:'fullName',label:'Full name',type:'text',required:true},{name:'email',label:'Email',type:'email',required:true},{name:'phone',label:'Phone number',type:'tel'},{name:'role',label:'Role',type:'text',required:true},{name:'active',label:'Status',type:'checkbox'}],organizations:[{name:'name',label:'Organization name',type:'text',required:true},{name:'type',label:'Organization type',type:'text'},{name:'address',label:'Address',type:'text'},{name:'active',label:'Status',type:'checkbox'}],'queue-settings':[{name:'branchId',label:'Branch ID',type:'text',required:true},{name:'maxQueueCapacity',label:'Maximum queue capacity',type:'number',required:true},{name:'notifyAheadCount',label:'Notify customers this many places ahead',type:'number'},{name:'allowRemoteJoin',label:'Remote queue joining',type:'checkbox'}],'operating-hours':[{name:'branchId',label:'Branch ID',type:'text',required:true},{name:'openingTime',label:'Opening time',type:'time',required:true},{name:'closingTime',label:'Closing time',type:'time',required:true},{name:'breakStart',label:'Break starts',type:'time'},{name:'breakEnd',label:'Break ends',type:'time'},{name:'holidayDates',label:'Holiday dates (comma separated)',type:'text'}]};return byResource[resource]??[];}
}

@Component({standalone:true,imports:[RouterLink],template:`<section class="empty-panel"><span>⌑</span><h2>You're not allowed to view this page.</h2><p>Your account doesn't have permission to access this area.</p><a class="button button-primary" routerLink="/">Return home</a></section>`}) export class ForbiddenPage {}
